using System.Text.RegularExpressions;

public static class EmailValidator
{
    // BUG: the nested quantifier ([a-zA-Z0-9]+)+ has exponentially many ways
    // to partition a run of matching characters - catastrophic backtracking
    // on a hostile input that almost-but-doesn't match (many 'a's followed
    // by a character the pattern rejects) can hang the process for seconds
    // to minutes.
    private static readonly Regex Pattern = new Regex(@"^([a-zA-Z0-9]+)+@[a-zA-Z]+\.[a-zA-Z]+$");

    public static bool IsValid(string email) => Pattern.IsMatch(email);
}

