using System;
using System.Diagnostics;
using Xunit;

public class EmailValidatorTests
{
    [Fact]
    public void ValidEmailsPass()
    {
        Assert.True(EmailValidator.IsValid("user@example.com"));
        Assert.True(EmailValidator.IsValid("a1b2@example.org"));
    }

    [Fact]
    public void ObviouslyInvalidEmailsFail()
    {
        Assert.False(EmailValidator.IsValid("not-an-email"));
        Assert.False(EmailValidator.IsValid("@example.com"));
    }

    [Fact]
    public void HostileInputIsRejectedQuickly()
    {
        // Calibrated: the vulnerable nested-quantifier pattern takes ~2.6s
        // in-container on this 26-character near-miss; a fixed (non-nested)
        // pattern - or one with an actual guard - resolves in low
        // milliseconds. A timeout-only band-aid still ties up the caller for
        // close to its full timeout window instead of failing fast.
        var hostile = new string('a', 26) + "!";

        var sw = Stopwatch.StartNew();
        var result = EmailValidator.IsValid(hostile);
        sw.Stop();

        Assert.False(result);
        Assert.True(
            sw.ElapsedMilliseconds < 500,
            $"IsValid took {sw.ElapsedMilliseconds}ms on a hostile near-miss string - " +
                "expected a regex with no catastrophic backtracking, not a timeout band-aid " +
                "on the same vulnerable pattern"
        );
    }
}

